mapper.select:
SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, c.assistant_teacher_ids, c.cover_image_url, c.status, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id
c.is_deleted = 0 AND t.is_deleted = 0
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.semester = #{semester}
AND c.teacher_id = #{teacherId}
AND c.status = #{status}
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
AND c.create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY c.create_time DESC

SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, c.assistant_teacher_ids, c.cover_image_url, c.status, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id
c.is_deleted = 0 AND t.is_deleted = 0
AND c.teacher_id = #{teacherId}
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.semester = #{semester}
AND c.status = #{status}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY c.create_time DESC

SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, c.assistant_teacher_ids, c.cover_image_url, c.status, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id
c.is_deleted = 0 AND t.is_deleted = 0
AND c.id NOT IN ( SELECT course_id FROM mg_course_student WHERE student_id = #{studentId} AND status = 0 )
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.semester = #{semester}
AND c.teacher_id = #{teacherId}
AND c.status = #{status}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY c.create_time DESC
